  nchunks = 1;
  clevel = 0;
  nthreads = 2;
  mu_run_test(test_lazy_chunk);

  nchunks = 10;
  clevel = 5;
  nthreads = 1;
  mu_run_test(test_lazy_chunk);

  nchunks = 10;
